const cors = require('cors');

module.exports = cors({
  origin: (origin, cb) => {
    const allowed = ['{{allowed_origin}}'];
    if (!origin || allowed.includes(origin)) cb(null, true);
    else cb(new Error('CORS blocked: ' + origin));
  },
  methods: '{{allowed_methods}}'.split(','),
  credentials: true,
  maxAge: 86400
});
